def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp = [o for _, o in history]
    me = [m for m, _ in history]
    opp_def = sum(1 for o in opp if o == 'D')
    my_def = sum(1 for m in me if m == 'D')
    coop = n - opp_def

    # Endgame exploitation if opponent is generally cooperative.
    if n >= 96:
        if coop > opp_def:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Opponent heavily defecting -> defect.
    if opp_def * 2 > n:
        if opp_last == 'D' or my_last == 'C':
            return 'D'
        return 'D' if rng.random() < 0.8 else 'C'

    # Current defection streak.
    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    # Long defection streak: mostly retaliate, occasionally test.
    if streak >= 4:
        return 'D' if rng.random() < 0.9 else 'C'
    if streak == 3:
        return 'D'
    if streak == 2:
        return 'D' if rng.random() < 0.85 else 'C'
    if opp_last == 'D':
        # Forgiving response to mild recent defection if overall cooperative.
        if coop * 3 > n * 2 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if n >= 10:
        recent = opp[-10:]
        rd = 0
        for a in recent:
            if a == 'D':
                rd += 1
        if rd >= 4:
            return 'D' if rng.random() < 0.7 else 'C'
    # Avoid being too exploitable: if we defected far more, return to C.
    if my_def > opp_def + 3 and rng.random() < 0.7:
        return 'C'
    # Occasional probe against a very cooperative opponent.
    if opp_def == 0 and n > 20 and n < 90 and rng.random() < 0.04:
        return 'D'
    return 'C'
